package org.tzi.use.plugins.jacamo.semantics;

import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.tzi.use.api.UseModelApi;
import org.tzi.use.plugins.jacamo.semantics.exploration.*;
import org.tzi.use.plugins.jacamo.semantics.istar.*;
import static org.tzi.use.plugins.jacamo.semantics.exploration.ConformanceSummary.*;

class BoundedExplorerTest {
    static final ExplorationBounds B=new ExplorationBounds(8,100,20,2,4,10,10000);
    static TransitionProfile.State state(int value,String pc,long clock){return new TransitionProfile.State(Map.of("x",Map.of("p",new TransitionProfile.Scalar("Integer",Integer.toString(value)))),Map.of("A",pc),clock);}
    static RequirementModel req(RequirementModel.Temporal type){var binding=new RequirementModel.Binding("actor","A","role","ctx","x","X","episode");return new RequirementModel(List.of(new RequirementModel.Node("root","r",RequirementModel.Kind.GOAL,type,binding,"self.p > 0","true",RequirementModel.Refinement.NONE,List.of(),"","")));}
    static UseModelApi schema()throws Exception{var model=new UseModelApi("Finite");model.createClass("X",false);model.createAttribute("X","p","Integer");return model;}
    static TransitionProfile.Transition edge(String id,String actor,String from,String to,String post){return new TransitionProfile.Transition(id,"source:"+id,actor,from,to,"x","true",post,Map.of());}
    static TransitionProfile profile(Map<String,TransitionProfile.State> states,Set<String> terminal,List<TransitionProfile.Transition> edges,RequirementModel.Temporal type,boolean complete){return new TransitionProfile(TransitionProfile.VERSION,"source-rev",TransitionProfile.APPROVAL,complete,List.of(new TransitionProfile.ObjectDeclaration("x","X","source:artifact")),List.of(),states,Set.of("s"),terminal,edges,req(type),Set.of("root"),List.of("Fixed explicit object population and role bindings","No unmodelled effects, clocks, Java actions or external agents; finite table only"));}
    @Test void finiteOracleClassifiesAllMixedNoneAndUnknownWithoutGeneralMasClaim()throws Exception {
        var states=Map.of("s",state(0,"start",0),"yes",state(1,"end",1),"no",state(0,"end",1));var model=schema();var good=edge("good","A","s","yes","self.p = self.p@pre + 1");var bad=edge("bad","B","s","no","self.p = self.p@pre");
        var all=new BoundedExplorer().explore(model.getModel(),profile(states,Set.of("yes"),List.of(good),RequirementModel.Temporal.NONE,true),B);assertEquals(Status.CONFORMANT_WITHIN_BOUNDS,all.status());assertEquals(1,all.conformantScenarios());assertTrue(all.scope().contains("NO_JACAMO_BEHAVIORAL_EQUIVALENCE"));
        var mixed=new BoundedExplorer().explore(model.getModel(),profile(states,Set.of("yes","no"),List.of(good,bad),RequirementModel.Temporal.NONE,true),B);assertEquals(Status.WEAK,mixed.status());assertEquals(2,mixed.completeScenarios());assertEquals(Risk.VIOLATED_ROOT_WITNESS,mixed.risk());
        var none=new BoundedExplorer().explore(model.getModel(),profile(states,Set.of("no"),List.of(bad),RequirementModel.Temporal.NONE,true),B);assertEquals(Status.NON_CONFORMANT,none.status());
        assertEquals(Status.INCONCLUSIVE,new BoundedExplorer().explore(model.getModel(),profile(states,Set.of("no"),List.of(bad),RequirementModel.Temporal.ACHIEVE,true),B).status());
        assertEquals(Status.INCONCLUSIVE,new BoundedExplorer().explore(model.getModel(),profile(states,Set.of("yes"),List.of(good),RequirementModel.Temporal.NONE,false),B).status());assertTrue(all.portableBytes().length>100);
    }
    @Test void cutoffsDeadlockPopulationAndRejectedPostAreNeverSuccess()throws Exception {
        var model=schema();var loop=profile(Map.of("s",state(1,"loop",0)),Set.of(),List.of(edge("loop","A","s","s","self.p = self.p@pre")),RequirementModel.Temporal.MAINTAIN,true);var loopResult=new BoundedExplorer().explore(model.getModel(),loop,B);assertEquals(Status.INCONCLUSIVE,loopResult.status());assertEquals(0,loopResult.completeScenarios());assertTrue(loopResult.frontier().stream().anyMatch(f->f.reason().equals("LOOP_VISIT_BOUND")));
        var dead=profile(Map.of("s",state(1,"blocked",0)),Set.of(),List.of(),RequirementModel.Temporal.NONE,true);assertEquals(Status.INCONCLUSIVE,new BoundedExplorer().explore(model.getModel(),dead,B).status());
        var p=profile(Map.of("s",state(1,"start",0),"end",state(3,"end",1)),Set.of("end"),List.of(edge("wrong","A","s","end","self.p = self.p@pre + 1")),RequirementModel.Temporal.NONE,true);var rejected=new BoundedExplorer().explore(model.getModel(),p,B);assertEquals(Status.INCONCLUSIVE,rejected.status());assertTrue(rejected.frontier().stream().anyMatch(f->f.reason().equals("TRANSITION_POST_FAIL")));
        var noStep=new BoundedExplorer().explore(model.getModel(),p,new ExplorationBounds(0,10,10,1,1,10,10000));assertEquals("STEP_BOUND",noStep.frontier().getFirst().reason());var clock=new BoundedExplorer().explore(model.getModel(),p,new ExplorationBounds(8,10,10,1,1,0,10000));assertEquals(Status.INCONCLUSIVE,clock.status());
        var two=new TransitionProfile(p.version(),p.sourceRevision(),p.approval(),true,List.of(new TransitionProfile.ObjectDeclaration("x","X","source:x"),new TransitionProfile.ObjectDeclaration("y","X","source:y")),List.of(),p.states(),p.initial(),p.terminal(),p.transitions(),p.requirements(),p.roots(),p.assumptions());assertEquals("POPULATION_BOUND",new BoundedExplorer().explore(model.getModel(),two,new ExplorationBounds(8,10,10,1,1,10,10000)).frontier().getFirst().reason());
    }
    @Test void differentTemporalHistoriesAtTheSameDomainStateAreNeverMergedAndActorsInterleave()throws Exception {
        var states=Map.of("s",state(1,"start",0),"violation",state(0,"after-B",0),"end",state(1,"end",0));var p=profile(states,Set.of("end"),List.of(edge("A-first","A","s","end","true"),edge("B-first","B","s","violation","true"),edge("A-recover","A","violation","end","true")),RequirementModel.Temporal.MAINTAIN,true);var r=new BoundedExplorer().explore(schema().getModel(),p,B);assertEquals(Status.WEAK,r.status());assertEquals(2,r.completeScenarios());assertEquals(1,r.conformantScenarios());assertEquals(1,r.nonConformantScenarios());assertEquals(Set.of(IntentionalMarking.Status.SATISFIED,IntentionalMarking.Status.VIOLATED),new HashSet<>(r.witnesses().stream().filter(w->w.state().equals("end")).map(w->w.markings().get("root").evaluated()).toList()));
        var witness=r.witnesses().stream().filter(w->w.state().equals("end") && w.transitions().size()==2).findFirst().orElseThrow();var observations=new ArrayList<WitnessConcretizer.ObservedStep>();for(var id:witness.transitions()){var e=p.transitions().stream().filter(t->t.id().equals(id)).findFirst().orElseThrow();observations.add(new WitnessConcretizer.ObservedStep(e.sourceId(),e.actor(),states.get(e.from()),states.get(e.to()),true,"a".repeat(64)));}var concretizer=new WitnessConcretizer();assertEquals(WitnessConcretizer.Status.OBSERVED_VALUE_TRACE_MATCH,concretizer.match(p,witness,observations).status());var old=observations.getFirst();observations.set(0,new WitnessConcretizer.ObservedStep(old.sourceId(),"wrong actor",old.before(),old.after(),true,old.observationDigest()));assertEquals(WitnessConcretizer.Status.REJECTED_SPURIOUS,concretizer.match(p,witness,observations).status());
    }
    @Test void missingFrameArbitraryBehaviorAndBackendUndefinedAreExplicit()throws Exception {
        var model=schema();var missing=profile(Map.of("s",new TransitionProfile.State(Map.of("x",Map.of()),Map.of(),0)),Set.of("s"),List.of(),RequirementModel.Temporal.NONE,true);assertEquals(Status.UNSUPPORTED,new BoundedExplorer().explore(model.getModel(),missing,B).status());
        var original=profile(Map.of("s",state(1,"end",0)),Set.of("s"),List.of(),RequirementModel.Temporal.NONE,true);var javaProfile=new TransitionProfile(original.version(),original.sourceRevision(),"INFER_JAVA_EFFECT",true,original.population(),original.fixedLinks(),original.states(),original.initial(),original.terminal(),original.transitions(),original.requirements(),original.roots(),original.assumptions());assertEquals(Status.UNSUPPORTED,new BoundedExplorer().explore(model.getModel(),javaProfile,B).status());
        var binding=original.requirements().nodes().getFirst().binding();var unknown=new RequirementModel(List.of(new RequirementModel.Node("root","r",RequirementModel.Kind.GOAL,RequirementModel.Temporal.NONE,binding,"1 div 0 > 1","true",RequirementModel.Refinement.NONE,List.of(),"","")));var undefined=new TransitionProfile(original.version(),original.sourceRevision(),original.approval(),true,original.population(),original.fixedLinks(),original.states(),original.initial(),original.terminal(),original.transitions(),unknown,original.roots(),original.assumptions());assertEquals(Status.INCONCLUSIVE,new BoundedExplorer().explore(model.getModel(),undefined,B).status());
    }
}
